      </section>

      <MenuSection items={sampleMenuItems} />

      <AccessSection info={sampleAccessInfo} />

      <footer className="footer">
        <p>&copy; 2024 Lumina Cafe. All Rights Reserved.</p>
      </footer>

      <button
        onClick={scrollToTop}
        style={{
          position: 'fixed',
          bottom: '2rem',
          right: '2rem',
          backgroundColor: '#4a3b32',
          color: '#ffffff',
          border: 'none',
          borderRadius: '50%',
